import{_ as n,o as a,c as p,ae as e}from"./chunks/framework.Iv6F95cJ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/design-pattern/15 - 理论一：对于单一职责原则，如何判定某个类的职责是否够“单一”？.md","filePath":"books/design-pattern/15 - 理论一：对于单一职责原则，如何判定某个类的职责是否够“单一”？.md"}'),i={name:"books/design-pattern/15 - 理论一：对于单一职责原则，如何判定某个类的职责是否够“单一”？.md"};function l(t,s,r,o,c,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<p>上几节课中，我们介绍了面向对象相关的知识。从今天起，我们开始学习一些经典的设计原则，其中包括，SOLID、KISS、YAGNI、DRY、LOD等。</p><p>这些设计原则，从字面上理解，都不难。你一看就感觉懂了，一看就感觉掌握了，但真的用到项目中的时候，你会发现，“看懂”和“会用”是两回事，而“用好”更是难上加难。从我之前的工作经历来看，很多同事因为对这些原则理解得不够透彻，导致在使用的时候过于教条主义，拿原则当真理，生搬硬套，适得其反。</p><p>所以，在接下来的讲解中，我不仅会讲解这些原则的定义，还会解释这些原则设计的初衷，能解决哪些问题，有哪些应用场景等，让你知其然知其所以然。在学习的时候，希望你能跟上我的思路，把握住重点，真正做到活学活用。</p><h2 id="如何理解单一职责原则-srp" tabindex="-1">如何理解单一职责原则（SRP）？ <a class="header-anchor" href="#如何理解单一职责原则-srp" aria-label="Permalink to &quot;如何理解单一职责原则（SRP）？&quot;">&amp;ZeroWidthSpace;</a></h2><p>文章的开头我们提到了SOLID原则，实际上，SOLID原则并非单纯的1个原则，而是由5个设计原则组成的，它们分别是：单一职责原则、开闭原则、里式替换原则、接口隔离原则和依赖反转原则，依次对应SOLID中的S、O、L、I、D这5个英文字母。我们今天要学习的是SOLID原则中的第一个原则：单一职责原则。</p><p>单一职责原则的英文是Single Responsibility Principle，缩写为SRP。这个原则的英文描述是这样的：A class or module should have a single responsibility。如果我们把它翻译成中文，那就是：一个类或者模块只负责完成一个职责（或者功能）。</p><p>注意，这个原则描述的对象包含两个，一个是类（class），一个是模块（module）。关于这两个概念，在专栏中，有两种理解方式。一种理解是：把模块看作比类更加抽象的概念，类也可以看作模块。另一种理解是：把模块看作比类更加粗粒度的代码块，模块中包含多个类，多个类组成一个模块。</p><p>不管哪种理解方式，单一职责原则在应用到这两个描述对象的时候，道理都是相通的。为了方便你理解，接下来我只从“类”设计的角度，来讲解如何应用这个设计原则。对于“模块”来说，你可以自行引申。</p><p>单一职责原则的定义描述非常简单，也不难理解。一个类只负责完成一个职责或者功能。也就是说，不要设计大而全的类，要设计粒度小、功能单一的类。换个角度来讲就是，一个类包含了两个或者两个以上业务不相干的功能，那我们就说它职责不够单一，应该将它拆分成多个功能更加单一、粒度更细的类。</p><p>我举一个例子来解释一下。比如，一个类里既包含订单的一些操作，又包含用户的一些操作。而订单和用户是两个独立的业务领域模型，我们将两个不相干的功能放到同一个类中，那就违反了单一职责原则。为了满足单一职责原则，我们需要将这个类拆分成两个粒度更细、功能更加单一的两个类：订单类和用户类。</p><h2 id="如何判断类的职责是否足够单一" tabindex="-1">如何判断类的职责是否足够单一？ <a class="header-anchor" href="#如何判断类的职责是否足够单一" aria-label="Permalink to &quot;如何判断类的职责是否足够单一？&quot;">&amp;ZeroWidthSpace;</a></h2><p>从刚刚这个例子来看，单一职责原则看似不难应用。那是因为我举的这个例子比较极端，一眼就能看出订单和用户毫不相干。但大部分情况下，类里的方法是归为同一类功能，还是归为不相关的两类功能，并不是那么容易判定的。在真实的软件开发中，对于一个类是否职责单一的判定，是很难拿捏的。我举一个更加贴近实际的例子来给你解释一下。</p><p>在一个社交产品中，我们用下面的UserInfo类来记录用户的信息。你觉得，UserInfo类的设计是否满足单一职责原则呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class UserInfo {</span></span>
<span class="line"><span>  private long userId;</span></span>
<span class="line"><span>  private String username;</span></span>
<span class="line"><span>  private String email;</span></span>
<span class="line"><span>  private String telephone;</span></span>
<span class="line"><span>  private long createTime;</span></span>
<span class="line"><span>  private long lastLoginTime;</span></span>
<span class="line"><span>  private String avatarUrl;</span></span>
<span class="line"><span>  private String provinceOfAddress; // 省</span></span>
<span class="line"><span>  private String cityOfAddress; // 市</span></span>
<span class="line"><span>  private String regionOfAddress; // 区 </span></span>
<span class="line"><span>  private String detailedAddress; // 详细地址</span></span>
<span class="line"><span>  // ...省略其他属性和方法...</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>对于这个问题，有两种不同的观点。一种观点是，UserInfo类包含的都是跟用户相关的信息，所有的属性和方法都隶属于用户这样一个业务模型，满足单一职责原则；另一种观点是，地址信息在UserInfo类中，所占的比重比较高，可以继续拆分成独立的UserAddress类，UserInfo只保留除Address之外的其他信息，拆分之后的两个类的职责更加单一。</p><p>哪种观点更对呢？实际上，要从中做出选择，我们不能脱离具体的应用场景。如果在这个社交产品中，用户的地址信息跟其他信息一样，只是单纯地用来展示，那UserInfo现在的设计就是合理的。但是，如果这个社交产品发展得比较好，之后又在产品中添加了电商的模块，用户的地址信息还会用在电商物流中，那我们最好将地址信息从UserInfo中拆分出来，独立成用户物流信息（或者叫地址信息、收货信息等）。</p><p>我们再进一步延伸一下。如果做这个社交产品的公司发展得越来越好，公司内部又开发出了很多其他产品（可以理解为其他App）。公司希望支持统一账号系统，也就是用户一个账号可以在公司内部的所有产品中登录。这个时候，我们就需要继续对UserInfo进行拆分，将跟身份认证相关的信息（比如，email、telephone等）抽取成独立的类。</p><p>从刚刚这个例子，我们可以总结出，不同的应用场景、不同阶段的需求背景下，对同一个类的职责是否单一的判定，可能都是不一样的。在某种应用场景或者当下的需求背景下，一个类的设计可能已经满足单一职责原则了，但如果换个应用场景或着在未来的某个需求背景下，可能就不满足了，需要继续拆分成粒度更细的类。</p><p>除此之外，从不同的业务层面去看待同一个类的设计，对类是否职责单一，也会有不同的认识。比如，例子中的UserInfo类。如果我们从“用户”这个业务层面来看，UserInfo包含的信息都属于用户，满足职责单一原则。如果我们从更加细分的“用户展示信息”“地址信息”“登录认证信息”等等这些更细粒度的业务层面来看，那UserInfo就应该继续拆分。</p><p>综上所述，评价一个类的职责是否足够单一，我们并没有一个非常明确的、可以量化的标准，可以说，这是件非常主观、仁者见仁智者见智的事情。实际上，在真正的软件开发中，我们也没必要过于未雨绸缪，过度设计。所以，<strong>我们可以先写一个粗粒度的类，满足业务需求。随着业务的发展，如果粗粒度的类越来越庞大，代码越来越多，这个时候，我们就可以将这个粗粒度的类，拆分成几个更细粒度的类。这就是所谓的持续重构</strong>（后面的章节中我们会讲到）。</p><p>听到这里，你可能会说，这个原则如此含糊不清、模棱两可，到底该如何拿捏才好啊？我这里还有一些小技巧，能够很好地帮你，从侧面上判定一个类的职责是否够单一。而且，我个人觉得，下面这几条判断原则，比起很主观地去思考类是否职责单一，要更有指导意义、更具有可执行性：</p><ul><li>类中的代码行数、函数或属性过多，会影响代码的可读性和可维护性，我们就需要考虑对类进行拆分；</li><li>类依赖的其他类过多，或者依赖类的其他类过多，不符合高内聚、低耦合的设计思想，我们就需要考虑对类进行拆分；</li><li>私有方法过多，我们就要考虑能否将私有方法独立到新的类中，设置为public方法，供更多的类使用，从而提高代码的复用性；</li><li>比较难给类起一个合适名字，很难用一个业务名词概括，或者只能用一些笼统的Manager、Context之类的词语来命名，这就说明类的职责定义得可能不够清晰；</li><li>类中大量的方法都是集中操作类中的某几个属性，比如，在UserInfo例子中，如果一半的方法都是在操作address信息，那就可以考虑将这几个属性和对应的方法拆分出来。</li></ul><p>不过，你可能还会有这样的疑问：在上面的判定原则中，我提到类中的代码行数、函数或者属性过多，就有可能不满足单一职责原则。那多少行代码才算是行数过多呢？多少个函数、属性才称得上过多呢？</p><p>比较初级的工程师经常会问这类问题。实际上，这个问题并不好定量地回答，就像你问大厨“放盐少许”中的“少许”是多少，大厨也很难告诉你一个特别具体的量值。</p><p>如果继续深究一下的话，你可能还会说，一些菜谱确实给出了，做某某菜需要放多少克盐，放多少克油的具体量值啊。我想说的是，那是给家庭主妇用的，那不是给专业的大厨看的。类比一下做饭，如果你是没有太多项目经验的编程初学者，实际上，我也可以给你一个凑活能用、比较宽泛的、可量化的标准，那就是一个类的代码行数最好不能超过200行，函数个数及属性个数都最好不要超过10个。</p><p>实际上， 从另一个角度来看，当一个类的代码，读起来让你头大了，实现某个功能时不知道该用哪个函数了，想用哪个函数翻半天都找不到了，只用到一个小功能要引入整个类（类中包含很多无关此功能实现的函数）的时候，这就说明类的行数、函数、属性过多了。实际上，等你做多项目了，代码写多了，在开发中慢慢“品尝”，自然就知道什么是“放盐少许”了，这就是所谓的“专业第六感”。</p><h2 id="类的职责是否设计得越单一越好" tabindex="-1">类的职责是否设计得越单一越好？ <a class="header-anchor" href="#类的职责是否设计得越单一越好" aria-label="Permalink to &quot;类的职责是否设计得越单一越好？&quot;">&amp;ZeroWidthSpace;</a></h2><p>为了满足单一职责原则，是不是把类拆得越细就越好呢？答案是否定的。我们还是通过一个例子来解释一下。Serialization类实现了一个简单协议的序列化和反序列功能，具体代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/**</span></span>
<span class="line"><span> * Protocol format: identifier-string;{gson string}</span></span>
<span class="line"><span> * For example: UEUEUE;{&quot;a&quot;:&quot;A&quot;,&quot;b&quot;:&quot;B&quot;}</span></span>
<span class="line"><span> */</span></span>
<span class="line"><span>public class Serialization {</span></span>
<span class="line"><span>  private static final String IDENTIFIER_STRING = &quot;UEUEUE;&quot;;</span></span>
<span class="line"><span>  private Gson gson;</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public Serialization() {</span></span>
<span class="line"><span>    this.gson = new Gson();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public String serialize(Map&lt;String, String&gt; object) {</span></span>
<span class="line"><span>    StringBuilder textBuilder = new StringBuilder();</span></span>
<span class="line"><span>    textBuilder.append(IDENTIFIER_STRING);</span></span>
<span class="line"><span>    textBuilder.append(gson.toJson(object));</span></span>
<span class="line"><span>    return textBuilder.toString();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public Map&lt;String, String&gt; deserialize(String text) {</span></span>
<span class="line"><span>    if (!text.startsWith(IDENTIFIER_STRING)) {</span></span>
<span class="line"><span>        return Collections.emptyMap();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    String gsonStr = text.substring(IDENTIFIER_STRING.length());</span></span>
<span class="line"><span>    return gson.fromJson(gsonStr, Map.class);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果我们想让类的职责更加单一，我们对Serialization类进一步拆分，拆分成一个只负责序列化工作的Serializer类和另一个只负责反序列化工作的Deserializer类。拆分后的具体代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class Serializer {</span></span>
<span class="line"><span>  private static final String IDENTIFIER_STRING = &quot;UEUEUE;&quot;;</span></span>
<span class="line"><span>  private Gson gson;</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public Serializer() {</span></span>
<span class="line"><span>    this.gson = new Gson();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public String serialize(Map&lt;String, String&gt; object) {</span></span>
<span class="line"><span>    StringBuilder textBuilder = new StringBuilder();</span></span>
<span class="line"><span>    textBuilder.append(IDENTIFIER_STRING);</span></span>
<span class="line"><span>    textBuilder.append(gson.toJson(object));</span></span>
<span class="line"><span>    return textBuilder.toString();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class Deserializer {</span></span>
<span class="line"><span>  private static final String IDENTIFIER_STRING = &quot;UEUEUE;&quot;;</span></span>
<span class="line"><span>  private Gson gson;</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public Deserializer() {</span></span>
<span class="line"><span>    this.gson = new Gson();</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  public Map&lt;String, String&gt; deserialize(String text) {</span></span>
<span class="line"><span>    if (!text.startsWith(IDENTIFIER_STRING)) {</span></span>
<span class="line"><span>        return Collections.emptyMap();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    String gsonStr = text.substring(IDENTIFIER_STRING.length());</span></span>
<span class="line"><span>    return gson.fromJson(gsonStr, Map.class);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>虽然经过拆分之后，Serializer类和Deserializer类的职责更加单一了，但也随之带来了新的问题。如果我们修改了协议的格式，数据标识从“UEUEUE”改为“DFDFDF”，或者序列化方式从JSON改为了XML，那Serializer类和Deserializer类都需要做相应的修改，代码的内聚性显然没有原来Serialization高了。而且，如果我们仅仅对Serializer类做了协议修改，而忘记了修改Deserializer类的代码，那就会导致序列化、反序列化不匹配，程序运行出错，也就是说，拆分之后，代码的可维护性变差了。</p><p>实际上，不管是应用设计原则还是设计模式，最终的目的还是提高代码的可读性、可扩展性、复用性、可维护性等。我们在考虑应用某一个设计原则是否合理的时候，也可以以此作为最终的考量标准。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">&amp;ZeroWidthSpace;</a></h2><p>今天的内容到此就讲完了。我们来一块总结回顾一下，你应该掌握的重点内容。</p><p><strong>1.如何理解单一职责原则（SRP）？</strong></p><p>一个类只负责完成一个职责或者功能。不要设计大而全的类，要设计粒度小、功能单一的类。单一职责原则是为了实现代码高内聚、低耦合，提高代码的复用性、可读性、可维护性。</p><p><strong>2.如何判断类的职责是否足够单一？</strong></p><p>不同的应用场景、不同阶段的需求背景、不同的业务层面，对同一个类的职责是否单一，可能会有不同的判定结果。实际上，一些侧面的判断指标更具有指导意义和可执行性，比如，出现下面这些情况就有可能说明这类的设计不满足单一职责原则：</p><ul><li>类中的代码行数、函数或者属性过多；</li><li>类依赖的其他类过多，或者依赖类的其他类过多；</li><li>私有方法过多；</li><li>比较难给类起一个合适的名字；</li><li>类中大量的方法都是集中操作类中的某几个属性。</li></ul><p><strong>3.类的职责是否设计得越单一越好？</strong></p><p>单一职责原则通过避免设计大而全的类，避免将不相关的功能耦合在一起，来提高类的内聚性。同时，类职责单一，类依赖的和被依赖的其他类也会变少，减少了代码的耦合性，以此来实现代码的高内聚、低耦合。但是，如果拆分得过细，实际上会适得其反，反倒会降低内聚性，也会影响代码的可维护性。</p><h2 id="课堂讨论" tabindex="-1">课堂讨论 <a class="header-anchor" href="#课堂讨论" aria-label="Permalink to &quot;课堂讨论&quot;">&amp;ZeroWidthSpace;</a></h2><p>今天课堂讨论的话题有两个：</p><ol><li>对于如何判断一个类是否职责单一，如何判断代码行数过多，你还有哪些其他的方法吗？</li><li>单一职责原则，除了应用到类的设计上，还能延伸到哪些其他设计方面吗？</li></ol><p>欢迎在留言区写下你的答案，和同学一起交流和分享。如果有收获，也欢迎你把这篇文章分享给你的朋友。 精选留言（15） Luciano李鑫 👍（73） 💬（12）想请教一下争哥，关于代码代码持续重构的问题，所引出的额外测试、发布成本，和故障风险应该怎样平衡呢。2019-12-06一壶浊酒 👍（45） 💬（4）老师您好，有个问题想请教下，就是您举的UserInfo的例子，在抽取了地址相关的信息到新的类的时候，原来的userinfo类中需要再添加一个新的类的属性在里面么？感觉如果根据单一职责原则了话，新的类应该独立出来，UserInfo里应该不包含该类，那在这种情况下数据库的表一般会出现变化么？不然是否会造成一个新增的用户会在保存用户信息的时候对数据库进行两次操作？一次新增用户信息，然后获取了userId再进行一次操作修改地址相关信息？还是说在userinfo中存在新的地址相关类的属性，进行直接新增操作？因为没有这方面的实际经验，所以对这个比较疑惑。老师遇到这种情况一般作何处理2020-01-05Jxin 👍（16） 💬（12）回答问题： 1.不好说，职责单一这东西比较主观。得看自己对抽象出来的类的主观定义是什么。准的捏不住，但还是要把控一下范围的。 2.码出高效给出了方法行数不超过50行的一个基准标注。而我实践下来很难写出超过50行的方法，这50行还包括了大量注释。</p><p>3.方法的职责单一，业务领域的能力要单一（边界清晰）。</p><p>提问：</p><p>1.以前不代码规范不行，就逼着自己多思考，多写注释。现在养成了写注释的洁癖，不写就很难受。请问大佬，这怎么办，需要戒掉吗。我除了dao层的crud和数据类的setget外，其余方法都会带上注释。2019-12-06蚂蚁内推+v 👍（11） 💬（3）有个问题，比如有个OrderService中可能提供了各种订单查询、操作等，即一个OrderService有多个方法，是否符合SRP呢？2019-12-09刘学习来学习 👍（5） 💬（1）前段时间需要对外提供sdk,最开始的设计就是根据职责定义了多个client对象供其他系统调用，后来角色不是很友好，最后还是提供了个聚合类，将所有的接口都集中到一起对外提供了,像这种情况,有的时候不知道该参考什么来设计2020-01-07空也空 👍（4） 💬（6）“私有方法过多”为什么作为一个衡量标准呢？2020-04-10Cris 👍（2） 💬（3）老师，我今天听到了一个概念叫面向切片编程(aop)，它和面向对象编程有什么联系呢？想听听老师的理解2019-12-07tuyu 👍（1） 💬（2）小争哥, 数据库设计是不是不太适合设计那种抽象类的数据库表结构, 这样我写bo就会就会维护的很大很大2020-01-01刘同青 👍（0） 💬（1）老师，您好，我工作中遇到的就是面向过程编程，一个接口中只有一个方法，对应一个实现，然后通过dubbo rpc调用。。。请问如果一个接口中很多个方法，那实现类不就很复杂了么？2020-05-06L 👍（0） 💬（2）你好，我想问下如何在spring mvc下使用设计模式，或者说在框架下如何使用设计模式2019-12-06blacknhole 👍（377） 💬（28）在看文末的“3. 类的职责是否设计得越单一越好？”时，我惊喜地意识到：</p><p>1，内聚和耦合其实是对一个意思（即合在一块）从相反方向的两种阐述。</p><p>2，内聚是从功能相关来谈，主张高内聚。把功能高度相关的内容不必要地分离开，就降低了内聚性，成了低内聚。</p><p>3，耦合是从功能无关来谈，主张低耦合。把功能明显无关的内容随意地结合起来，就增加了耦合性，成了高耦合。2019-12-06编程界的小学生 👍（99） 💬（29）1.方法就是全凭感觉。感觉不爽，就尝试着是否可以拆分多个类，感觉来了谁也挡不住。没有硬性要求吧，都是凭借经验。比如用户service可能包含用户的登录注册修改密码忘记密码等等，这些操作都需要验证邮箱，这时候你会发现这个类就很乱，就可以把他一分为二，弄个UserService再弄个UserEmailService专门处理用户相关邮件的操作逻辑，让UserService依赖Email的，等等这种，我觉得真的是全凭经验。换句话说，屎一样的代码写多了，写到自己看着都想吐的时候，经验就积累了。 2.方法设计上也用到了，比如自上而下的编程方式，先把核心方法定义好在去写具体细节，不要上来就把所有的细节都写到一个大而全的方法里。自上而下的编程方式他不香吗？2019-12-06辣么大 👍（41） 💬（10）懂几个设计模式，只是花拳绣腿。掌握设计原则就才掌握了“道”。</p><p>设计你的系统，使得每个模块负责（响应）只满足一个业务功能需求。 Design your systems such that each module is responsible (responds to) the needs of just that one business function. (Robert C. Martin)</p><p>参考：https://blog.cleancoder.com/uncle-bob/2014/05/08/SingleReponsibilityPrinciple.html2019-12-06考休 👍（29） 💬（5）项目初始阶段也是雄心勃勃，要把系统做出一个快速迭代、维护性高的系统，可是不断的需求变更导致开发任务过重，留给项目整体的思考和重构时间被严重压缩，最终导致项目的技术管理失控，再加上人员变动等原因，项目死亡的概率急剧上升，都是惨痛的教训。</p><p>《三体》中常伟思的父亲经常说的是：要多想。</p><p>共勉！2019-12-09下雨天 👍（21） 💬（1）回答问题</p><ol><li><p>类单一职责判断可以通过评估其对外提供接口是否满足不断变化的业务和需求来确定！问自己，该类是否对其他类是&quot;黑盒&quot;！</p></li><li><p>类行数多=属性多+方法多 属性多: 要考虑这些属性是不是对类来说是必须的，需要移除么？ 方法多: 方法间复用情况，方法间有没有写重复代码？ 如上如果觉得没有可以改进的余地，就可以认为类行数恰当！</p></li><li><p>单一职责还可以应用到方法，模块，功能点上！2019-12-06</p></li></ol>`,57)])])}const S=n(i,[["render",l]]);export{g as __pageData,S as default};
